import javax.imageio.ImageIO;import java.nio.file.Path;
public class CompareCaptures{public static void main(String[] a)throws Exception{for(String p:new String[]{"initial","after-appearance"}){var n=ImageIO.read(Path.of(a[0],p+"-native.png").toFile());var c=ImageIO.read(Path.of(a[0],p+"-component-2x.png").toFile());int offset=n.getHeight()-c.getHeight(),different=0,heading=0;for(int y=0;y<c.getHeight();y++)for(int x=0;x<c.getWidth();x++)if(n.getRGB(x,y+offset)!=c.getRGB(x,y)){different++;if(x>=1300&&x<1800&&y>=330&&y<470)heading++;}System.out.printf("{\"phase\":\"%s\",\"native_width\":%d,\"native_height\":%d,\"component_width\":%d,\"component_height\":%d,\"titlebar_offset\":%d,\"different_root_pixels\":%d,\"different_heading_region_pixels\":%d}%n",p,n.getWidth(),n.getHeight(),c.getWidth(),c.getHeight(),offset,different,heading);}}}
